+  userEmail: string,
+  gracePeriodEndsAt: string
+): Promise<EmailResult> {
+  try {
+    const { data, error } = await supabase.functions.invoke('send-email', {
+      body: {
+        type: 'subscription_cancelled',
+        to: userEmail,
